BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(20);
SELECT ok(to_regclass('app_private.admission_number_series') IS NOT NULL,'P41 private admission number series exists');
SELECT ok(to_regclass('app_private.admission_number_allocations') IS NOT NULL,'P41 private admission number allocation ledger exists');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_numbering_profiles'::regclass AND conname='db03_number_profile_school_kind_key' AND contype='u' AND cardinality(conkey)=3),'number profile has school/kind scoped reference key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_applications'::regclass AND conname='db03_number_application_school_key' AND contype='u' AND cardinality(conkey)=2),'application has same-school scoped reference key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_series'::regclass AND contype='f' AND confrelid='app_private.admission_numbering_profiles'::regclass AND cardinality(conkey)=3),'series profile School and number Kind bound together');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_series'::regclass AND contype='f' AND confrelid='app.academic_years'::regclass AND cardinality(conkey)=2),'series year belongs to same School');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_allocations'::regclass AND contype='f' AND confrelid='app_private.admission_number_series'::regclass AND cardinality(conkey)=4),'allocation matches exact Series/School/Kind/Session');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_allocations'::regclass AND contype='f' AND confrelid='app_private.admission_applications'::regclass AND cardinality(conkey)=2),'allocation belongs to application School');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_series'::regclass AND conname='db03_number_series_profile_year' AND contype='u' AND cardinality(conkey)=2),'one Series per Profile and Academic Year');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_allocations'::regclass AND conname='db03_number_allocation_series_value' AND contype='u' AND cardinality(conkey)=2),'numeric value never reused within a Series');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_allocations'::regclass AND conname='db03_number_allocation_rendered_unique' AND contype='u' AND cardinality(conkey)=3),'rendered number unique per School and Kind');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_allocations'::regclass AND conname='db03_number_application_kind_unique' AND contype='u' AND cardinality(conkey)=2),'one retained number per application and Kind');
SELECT ok((SELECT count(*)>=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_allocations'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%CANCELED%'),'cancellation retains complete metadata');
SELECT ok((SELECT count(*)=2 FROM pg_class WHERE oid IN('app_private.admission_number_series'::regclass,'app_private.admission_number_allocations'::regclass) AND relrowsecurity AND relforcerowsecurity),'both new relations enforce RLS');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_number_series','INSERT') AND NOT has_table_privilege('service_role','app_private.admission_number_series','INSERT') AND NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_number_allocations','INSERT') AND NOT has_table_privilege('schoolos_student_executor','app_private.admission_number_allocations','INSERT'),'no client or server writer grants');
SELECT ok((SELECT count(*)=2 FROM pg_trigger WHERE tgname IN('db03_number_series_mutation_disabled','db03_number_allocations_mutation_disabled') AND NOT tgisinternal),'both number storages deny row mutations');
SELECT ok((SELECT count(*)=2 FROM pg_trigger WHERE tgname IN('db03_number_series_no_truncate','db03_number_allocations_no_truncate') AND NOT tgisinternal),'both number storages deny truncate');
SELECT throws_ok($q$INSERT INTO app_private.admission_number_series DEFAULT VALUES$q$,'P0001','DB03 permanent number writer unavailable','number Series cannot be fabricated');
SELECT throws_ok($q$INSERT INTO app_private.admission_number_allocations DEFAULT VALUES$q$,'P0001','DB03 permanent number writer unavailable','number allocation cannot be fabricated');
SELECT ok(to_regprocedure('app.allocate_admission_number(uuid,uuid)') IS NULL AND to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'neither numbering nor Principal APPROVE activated');
SELECT * FROM finish();
ROLLBACK;
